  'aiworkspace.core.replica.stop.epochMismatch': 'История этого рабочего пространства заменена восстановлением: локальная копия и её ожидающие изменения основаны на старой истории. Отправка остановлена, ничего не удалено. Экспортируйте ожидающие изменения, затем удалите локальную копию и снова сделайте рабочее пространство доступным офлайн.',
