  'aiworkspace.demo.quarterly.introText': 'Это обычная таблица продаж за 2 квартал 2026 года: выручка, себестоимость, план и выручка прошлого квартала по регионам и товарам. Числа можно менять прямо в режиме источника данных, а нужный анализ — описать одной фразой в блоке желания на холсте, затем трижды нажать его кнопку: «Анализировать», «Написать макрос», «Запустить макрос». Результат каждого шага записывается сразу по его завершении; если он вас не устроил, вернитесь на предыдущую вкладку и запустите её заново либо откатите. Синяя пунктирная стрелка показывает, что желание читает, оранжевые — что оно создало. Когда данные изменятся, запустите макрос снова.',
