  'aiworkspace.demo.film.howto.text': 'Процесс генерации слева направо, где каждый узел — обычный объект холста: слева сценарий, таблица персонажей и стиль, которые можно править прямо здесь; каждый этап — блок желания, и на его карточке нужно по очереди нажать «Анализировать», «Написать макрос» и «Запустить макрос» — результат каждого шага записывается сразу по его завершении. Результат одного этапа служит входными данными следующего, поэтому запускайте этапы слева направо; синие пунктирные стрелки ведут от того, что желание читает, оранжевые — к тому, что оно создало. Если изменить таблицу персонажей или сценарий, результаты ниже по цепочке будут помечены как устаревшие; запустите их снова один за другим. Картинки и видео создают модели ИИ вашей Zone.',
  'aiworkspace.demo.film.surface': 'Процесс создания короткометражки',
  'aiworkspace.demo.film.wish1.title': 'Блок желания ①: создать листы персонажей',
  'aiworkspace.demo.film.wish1.prompt': 'По таблице «{{characters}}» и стилю «{{style}}» создай для каждого персонажа портретный лист с краткой справкой. Сохрани основной цвет и реквизит каждого персонажа, чтобы раскадровка могла ссылаться на них позже.',
  'aiworkspace.demo.film.wish1.output': 'Листы персонажей',
  'aiworkspace.demo.film.wish2.title': 'Блок желания ②: создать раскадровку',
  'aiworkspace.demo.film.wish2.prompt': 'По сценам из «{{script}}», а также по «{{sheets}}» и «{{style}}» создай раскадровку: по одному кадру на сцену; выведи список кадров (номер кадра, сцена, крупность плана, персонажи, действие, длительность) и изображение для каждого кадра.',
  'aiworkspace.demo.film.wish2.output': 'Раскадровка',
  'aiworkspace.demo.film.wish3.title': 'Блок желания ③: создать предпросмотр финального монтажа',
  'aiworkspace.demo.film.wish3.prompt': 'По «{{storyboard}}» создай видео предпросмотра финального монтажа: один непрерывный клип примерно на 8 секунд (16:9), следующий кадрам в порядке списка, с изображением первого кадра в качестве опорной картинки; также напиши заметку с числом кадров и общей длительностью по списку кадров.',
  'aiworkspace.demo.film.wish3.output': 'Финальный монтаж',
  'aiworkspace.demo.film.commit.data': 'Сценарий, таблица персонажей, стиль',
  'aiworkspace.demo.film.commit.canvas': 'Холст рабочего процесса',
